var DOLLAR = String.fromCharCode(36), SPECIAL = '.*+?^()|[]' + String.fromCharCode(92) + DOLLAR;
function esc(s) { var o = ''; for (var i = 0; i < s.length; i++) { var ch = s.charAt(i); o += SPECIAL.indexOf(ch) >= 0 ? String.fromCharCode(92) + ch : ch; } return o; }
var c = NPDevI18n.catalogue(); var en = c.stringsByLocale.en, pt = c.stringsByLocale.pt; var pats = [];
Object.keys(en).forEach(function (k) { var e = en[k]; if (!pt[k] || pt[k] === e || e.length < 3) return; var parts = e.split(/\{[A-Za-z0-9_]+\}/); var literal = parts.join('').trim().length; if (parts.length > 1 && literal < 6) return; pats.push([new RegExp('^' + parts.map(esc).join('.{1,60}') + DOLLAR), k, e]); });
function ownText(t, e) { return t.indexOf('Create the order, then add its lines') === 0 || (t === 'Export CSV' && /ReviewPanel/.test(where(e))); } /* the sample model's own help text and its own 'Export CSV' action label, not platform text */
function hit(t) { t = (t || '').replace(/\s+/g, ' ').trim(); if (t.length < 3 || t.length > 300) return null; for (var i = 0; i < pats.length; i++) { if (pats[i][0].test(t)) return pats[i][1] + '=' + t.slice(0, 60); } return null; }
function where(e) { var id = e.closest('[id]'); return (e.tagName + '.' + String(e.className).split(' ')[0] + ' in #' + (id ? id.id : '?')); }
var left = [], w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (w.nextNode()) { var n = w.currentNode; var pe = n.parentElement; if (!pe || /^(SCRIPT|STYLE|TH|TD|LABEL|OPTION)$/.test(pe.tagName) || pe.id === 'i18n-audit' || pe.closest('th,td,label,option,.badge')) continue; var h = ownText((n.nodeValue||'').trim(), pe) ? null : hit(n.nodeValue); if (h) left.push(h + ' @ ' + where(pe)); }
Array.prototype.forEach.call(document.querySelectorAll('[placeholder],[title],[aria-label]'), function (e) { ['placeholder', 'title', 'aria-label'].forEach(function (a) { var h = hit(e.getAttribute(a)); if (h) left.push(a + ':' + h + ' @ ' + where(e)); }); });
var o = document.getElementById('i18n-audit'); if (!o) { o = document.createElement('pre'); o.id = 'i18n-audit'; document.body.appendChild(o); }
o.textContent = 'ENGLISH-LEFT: ' + left.length + ' ' + left.slice(0, 12).join(' | '); return { left: left, patterns: pats.length };

